const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const indiaStates = ee.FeatureCollection('FAO/GAUL/2012/v1').filter(ee.Filter.eq('ADM0_NAME', 'India'));
    const punjab = indiaStates.filter(ee.Filter.eq('ADM1_NAME', 'Punjab'));
    const haryana = indiaStates.filter(ee.Filter.eq('ADM1_NAME', 'Haryana'));
    const region = punjab.merge(haryana).geometry();

    const startYear = 2012;
    const endYear = 2024; // Including 2024 for "to 2024"

    // 2. Data Acquisition
    const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML');

    // Filter the entire collection once for the full date range and region
    const fullFireCollection = fireCollection
      .filterBounds(region)
      .filterDate(`${startYear}-01-01`, `${endYear + 1}-01-01`);

    const fireCollectionSize = fullFireCollection.size().getInfo();
    if (fireCollectionSize === 0) {
      console.log("No fire detections found in the specified region and date range.");
      console.log("C1");
      return;
    }
    console.log(`Total fire detections in region (${startYear}-${endYear}): ${fireCollectionSize}`);

    let maxFireCount = -1;
    let maxFireYear = null;
    let fireCount2016 = null;
    const yearlyCounts = {};

    // 3. Processing and Calculation
    for (let year = startYear; year <= endYear; year++) {
      const yearStartDate = `${year}-01-01`;
      const yearEndDate = `${year + 1}-01-01`;

      const yearlyFires = fullFireCollection.filterDate(yearStartDate, yearEndDate);
      const currentYearFireCount = yearlyFires.size().getInfo();
      yearlyCounts[year] = currentYearFireCount;

      if (currentYearFireCount > maxFireCount) {
        maxFireCount = currentYearFireCount;
        maxFireYear = year;
      }
      if (year === 2016) {
        fireCount2016 = currentYearFireCount;
      }
      console.log(`Fires in ${year}: ${currentYearFireCount}`);
    }

    if (fireCount2016 === null) {
      console.log("Calculation failure: 2016 fire count not retrieved.");
      console.log("C3");
      return;
    }

    // 4. Validation & Final Answer
    console.log(`2016 Fire Detections: ${fireCount2016}`);
    console.log(`Maximum Fire Detections: ${maxFireCount} in ${maxFireYear}`);

    if (fireCount2016 === maxFireCount && maxFireYear === 2016) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (e) {
    console.error("An error occurred during analysis:", e);
    // D for general errors, C3 for specific calculation issues
    if (e.message.includes('Collection.filter')) { // Example of catching a specific type of error
      console.log("D");
    } else if (e.message.includes('property')) { // Missing property, often syntax or incorrect band name
      console.log("D");
    } else {
      console.log("D");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
